<script setup>
import { computed, onMounted, reactive, ref, watch } from "vue";
import { useAuthStore } from "@/stores/auth.store";
import { useFeedback } from "@/composables/useFeedback";
import BaseButton from "@/components/ui/BaseButton.vue";
import StatCard from "@/components/ui/StatCard.vue";
import TemplateFormModal from "../components/TemplateFormModal.vue";
import UseTemplateModal from "../components/UseTemplateModal.vue";
import UsageEditModal from "../components/UsageEditModal.vue";
import { CHANNELS, createTemplate, deleteTemplate, deleteTemplateUsage, formatMinutes, getAllowedVariables, getMonthlyTotals, listTemplates, listUsageHistory, updateTemplate, updateTemplateUsage } from "../services/responseTemplates.service";
import { getResponseTemplateAccess } from "../services/responseTemplates.access";

const auth = useAuthStore(); const feedback = useFeedback();
const rows = ref([]); const history = ref([]); const totals = ref([]); const selected = ref(null);
const loading = ref(false); const historyLoading = ref(false); const loadError = ref(""); const historyError = ref(""); const totalsError = ref("");
const saving = ref(false); const formOpen = ref(false); const formTemplate = ref(null); const useOpen = ref(false);
const usageEditOpen = ref(false); const usageEditing = ref(null); const usageSaving = ref(false);
const now = new Date();
const filters = reactive({ region:"MX", search:"", category:"", language:"", channel:"", status:"" });
const historyFilters = reactive({ month:now.getMonth() + 1, year:now.getFullYear(), region:"", user:"", channel:"", currency:"" });
const access = computed(() => getResponseTemplateAccess(auth.user)); const variables = getAllowedVariables();
const categories = computed(() => [...new Set(rows.value.map((item) => item.category).filter(Boolean))].sort());
const visibleRows = computed(() => { const term = filters.search.trim().toLowerCase(); if (!term) return rows.value; return rows.value.filter((row) => [row.name,row.category,row.description,row.content].some((value) => String(value || "").toLowerCase().includes(term))); });
const monthValue = computed(() => `${historyFilters.year}-${String(historyFilters.month).padStart(2,"0")}-01`);
const summary = computed(() => {
  const result = { usages:0, minutes:0, MXN:0, USD:0 };
  for (const item of totals.value) { result.usages += Number(item.total_usages)||0; result.minutes += Number(item.total_minutes)||0; if (item.currency in result) result[item.currency] = Number(item.final_cost)||0; }
  return result;
});
const users = computed(() => [...new Set(history.value.map((item) => item.user_email).filter(Boolean))]);

function describeError(error) { const text = String(error?.message || ""); if (/permission|policy|rls|unauthorized|jwt/i.test(text)) return "Acceso no autorizado por Supabase. Verifica las políticas de la tabla."; if (/fetch|network|failed/i.test(text)) return "Error de conexión con Supabase. Revisa la red y la configuración."; return text || "No fue posible consultar Supabase."; }
async function loadTemplates() { loading.value=true; loadError.value=""; try { rows.value=await listTemplates(filters); if (filters.category && !rows.value.some((r)=>r.category===filters.category)) filters.category=""; if (selected.value) selected.value=rows.value.find((r)=>r.id===selected.value.id)||null; } catch(error){ console.error("[Response Templates]",error); loadError.value=describeError(error); rows.value=[]; } finally{loading.value=false;} }
function range() { const start=new Date(historyFilters.year,historyFilters.month-1,1); const end=new Date(historyFilters.year,historyFilters.month,1); return { start:start.toISOString(),end:end.toISOString() }; }
async function loadTotals(){ totalsError.value=""; try{totals.value=await getMonthlyTotals(monthValue.value);}catch(error){console.error("[Response Template Totals]",error); totalsError.value=describeError(error); totals.value=[];} }
async function loadHistory(){ historyLoading.value=true; historyError.value=""; try{history.value=await listUsageHistory({...historyFilters,...range()});}catch(error){console.error("[Response Template History]",error);historyError.value=describeError(error);history.value=[];}finally{historyLoading.value=false;} }
function switchRegion(region){filters.region=region;selected.value=null;}
function openCreate(){formTemplate.value={region:filters.region,language:filters.region==="MX"?"es":"en"};formOpen.value=true;}
function openEdit(row){formTemplate.value={...row};formOpen.value=true;}
async function save(payload){saving.value=true;try{const editing=Boolean(formTemplate.value?.id);const saved=editing?await updateTemplate(formTemplate.value.id,payload):await createTemplate(payload);filters.region=saved.region;formOpen.value=false;formTemplate.value=null;await loadTemplates();feedback.notify(editing?"Plantilla actualizada":"Plantilla guardada");}catch(error){feedback.error("No fue posible guardar la plantilla",error);}finally{saving.value=false;}}
async function remove(row){const answer=await feedback.confirm({title:"Eliminar plantilla",text:`Se archivará “${row.name}”.`,confirmButtonText:"Eliminar",cancelButtonText:"Cancelar",icon:"warning",confirmButtonColor:"#b91c1c"});if(!answer.isConfirmed)return;try{await deleteTemplate(row.id);await loadTemplates();feedback.notify("Plantilla eliminada");}catch(error){feedback.error("No fue posible eliminar",error);}}
function useTemplate(row){selected.value=row;useOpen.value=true;}
async function usageSaved(result){useOpen.value=false;feedback.notify(`Uso registrado correctamente · ${Number(result.calculated_cost).toFixed(2)} ${result.currency}`);await Promise.all([loadHistory(),loadTotals()]);}
function editUsage(item){usageEditing.value={...item};usageEditOpen.value=true;}
async function saveUsage(payload){usageSaving.value=true;try{const result=await updateTemplateUsage(usageEditing.value.id,payload);usageEditOpen.value=false;usageEditing.value=null;feedback.notify(`Registro actualizado · ${Number(result.calculated_cost).toFixed(2)} ${result.currency}`);await Promise.all([loadHistory(),loadTotals()]);}catch(error){feedback.error("No fue posible actualizar el registro",error);}finally{usageSaving.value=false;}}
async function removeUsage(item){const answer=await feedback.confirm({title:"Eliminar registro",text:"Se eliminará este uso y sus costos asociados.",confirmButtonText:"Eliminar",cancelButtonText:"Cancelar",icon:"warning",confirmButtonColor:"#b91c1c"});if(!answer.isConfirmed)return;try{await deleteTemplateUsage(item.id);feedback.notify("Registro eliminado");await Promise.all([loadHistory(),loadTotals()]);}catch(error){feedback.error("No fue posible eliminar el registro",error);}}
function money(value,currency){return new Intl.NumberFormat("es-MX",{style:"currency",currency}).format(Number(value)||0)+` ${currency}`;}
function date(value){return value?new Intl.DateTimeFormat("es-MX",{dateStyle:"medium",timeStyle:"short"}).format(new Date(value)):"—";}
watch(()=>[filters.region,filters.category,filters.language,filters.channel,filters.status],loadTemplates);
watch(()=>[historyFilters.month,historyFilters.year],()=>Promise.all([loadHistory(),loadTotals()]));
watch(()=>[historyFilters.region,historyFilters.user,historyFilters.channel,historyFilters.currency],loadHistory);
onMounted(async()=>{if(!auth.initialized)await auth.init();await Promise.all([loadTemplates(),loadHistory(),loadTotals()]);});
</script>

<template>
  <section class="templates-page page-shell">
    <div v-if="!access.canView" class="state-card"><h2>Acceso no autorizado</h2><p>Tu cuenta no tiene acceso a las plantillas.</p></div>
    <template v-else>
      <header class="page-header"><div><span class="eyebrow">Comunicación comercial</span><h1>Plantillas de respuesta</h1><p>Respuestas para clientes y registro manual de tiempo y costos</p></div><BaseButton v-if="access.canCreate" @click="openCreate">Nueva plantilla</BaseButton></header>
      <section class="stats"><StatCard title="Usos este mes" :value="summary.usages"/><StatCard title="Tiempo total" :value="formatMinutes(summary.minutes)"/><StatCard title="Costo final MXN" :value="money(summary.MXN,'MXN')"/><StatCard title="Costo final USD" :value="money(summary.USD,'USD')"/></section>
      <p v-if="totalsError" class="inline-error">{{ totalsError }}</p>
      <nav class="region-tabs"><button :class="{active:filters.region==='MX'}" @click="switchRegion('MX')">México</button><button :class="{active:filters.region==='USA'}" @click="switchRegion('USA')">USA</button></nav>
      <section class="filters"><input v-model="filters.search" type="search" placeholder="Buscar plantilla…"/><select v-model="filters.category"><option value="">Todas las categorías</option><option v-for="item in categories" :key="item">{{ item }}</option></select><select v-model="filters.language"><option value="">Todos los idiomas</option><option value="es">Español</option><option value="en">Inglés</option></select><select v-model="filters.channel"><option value="">Todos los canales</option><option v-for="item in CHANNELS" :key="item" :value="item">{{ item }}</option></select><select v-model="filters.status"><option value="">Todos los estados</option><option value="active">Activa</option><option value="inactive">Inactiva</option><option value="draft">Borrador</option><option value="archived">Archivada</option></select></section>
      <div v-if="loading" class="state-card">Cargando plantillas…</div><div v-else-if="loadError" class="state-card error-state"><p>{{ loadError }}</p><BaseButton @click="loadTemplates">Reintentar</BaseButton></div><div v-else-if="!visibleRows.length" class="state-card"><h2>Sin resultados reales</h2><p>Supabase no devolvió plantillas que coincidan con los filtros.</p></div>
      <div v-else class="workspace" :class="{detailed:selected}"><div class="cards"><article v-for="row in visibleRows" :key="row.id" class="template-card" @click="selected=row"><div class="card-head"><div><span class="category">{{ row.category }}</span><h2>{{ row.name }}</h2></div><span :class="['status',row.status]">{{ {active:'Activa',inactive:'Inactiva',draft:'Borrador',archived:'Archivada'}[row.status] }}</span></div><p class="preview">{{ row.content }}</p><div class="badges"><span>{{ row.region==='MX'?'México':'USA' }}</span><span>{{ row.language==='es'?'Español':'Inglés' }}</span><span v-for="channel in row.channels" :key="channel">{{ channel }}</span></div><footer><small>Actualizada {{ date(row.updated_at) }}</small><div class="card-actions"><button @click.stop="useTemplate(row)">Usar</button><button v-if="access.canEdit" @click.stop="openEdit(row)">Editar</button><button v-if="access.canDelete" class="danger" @click.stop="remove(row)">Eliminar</button></div></footer></article></div><aside v-if="selected" class="detail"><button class="detail-close" @click="selected=null">×</button><span class="category">{{ selected.category }}</span><h2>{{ selected.name }}</h2><p>{{ selected.description }}</p><strong>Contenido</strong><pre>{{ selected.content }}</pre><BaseButton @click="useTemplate(selected)">Usar plantilla</BaseButton></aside></div>
      <section class="history"><div class="section-head"><div><h2>Historial de uso y costos</h2><p>Registros del periodo seleccionado</p></div><div class="period"><select v-model.number="historyFilters.month"><option v-for="m in 12" :key="m" :value="m">{{ new Intl.DateTimeFormat('es-MX',{month:'long'}).format(new Date(2020,m-1,1)) }}</option></select><input v-model.number="historyFilters.year" type="number" min="2020" max="2100"/></div></div><div class="history-filters"><select v-model="historyFilters.region"><option value="">Todas las regiones</option><option value="MX">México</option><option value="USA">USA</option></select><select v-model="historyFilters.user"><option value="">Todos los usuarios</option><option v-for="item in users" :key="item">{{ item }}</option></select><select v-model="historyFilters.channel"><option value="">Todos los canales</option><option v-for="item in CHANNELS" :key="item">{{ item }}</option></select><select v-model="historyFilters.currency"><option value="">Todas las monedas</option><option>MXN</option><option>USD</option></select></div><div v-if="historyLoading" class="state-card">Cargando historial…</div><div v-else-if="historyError" class="state-card error-state">{{ historyError }}</div><div v-else-if="!history.length" class="state-card">Sin historial para este periodo.</div><div v-else class="table-wrap"><table><thead><tr><th>Fecha</th><th>Plantilla</th><th>Usuario</th><th>Cliente</th><th>Canal</th><th>Tiempo</th><th>Tarifa/h</th><th>Costo</th><th>Estado</th><th>Observaciones</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in history" :key="item.id"><td>{{ date(item.used_at) }}</td><td>{{ item.response_templates?.name||'—' }}</td><td>{{ item.user_name||item.user_email||'Administrador' }}</td><td>{{ item.recipient_name||'—' }}</td><td>{{ item.channel }}</td><td>{{ formatMinutes(item.duration_minutes) }}</td><td>{{ money(item.hourly_rate,item.currency) }}</td><td>{{ money(item.calculated_cost,item.currency) }}</td><td>{{ item.delivery_status }}</td><td>{{ item.notes||'—' }}</td><td><div class="row-actions"><button @click="editUsage(item)">Editar</button><button class="danger" @click="removeUsage(item)">Eliminar</button></div></td></tr></tbody></table></div></section>
      <TemplateFormModal :open="formOpen" :template="formTemplate" :categories="categories" :variables="variables" :saving="saving" @close="formOpen=false" @save="save"/>
      <UseTemplateModal :open="useOpen" :template="selected" :current-user="auth.user" @close="useOpen=false" @saved="usageSaved" @error="feedback.error('Error al registrar el uso',$event)"/>
      <UsageEditModal :open="usageEditOpen" :usage="usageEditing" :saving="usageSaving" @close="usageEditOpen=false" @save="saveUsage"/>
    </template>
  </section>
</template>

<style scoped>
.templates-page{display:flex;flex-direction:column;gap:18px}.page-header,.section-head{display:flex;justify-content:space-between;align-items:center;gap:18px}.eyebrow,.category{color:var(--primary);font-size:.75rem;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.page-header h1,.section-head h2{margin:4px 0;color:var(--text-strong)}.page-header p,.section-head p{margin:0;color:var(--text-muted)}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.region-tabs{display:flex;padding:5px;border:1px solid var(--border-color);border-radius:16px;background:var(--bg-surface);width:max-content}.region-tabs button{min-width:120px;padding:10px;border-radius:12px;background:transparent;color:var(--text-muted);font-weight:800}.region-tabs .active{background:var(--primary);color:#fff}.filters,.history-filters{display:grid;grid-template-columns:2fr repeat(4,1fr);gap:10px;padding:16px;border:1px solid var(--border-color);border-radius:18px;background:var(--bg-surface)}.filters input,.filters select,.history select,.history input{padding:10px}.state-card{padding:34px;text-align:center;border:1px solid var(--border-color);border-radius:20px;background:var(--bg-surface);color:var(--text-muted)}.error-state,.inline-error{color:var(--danger)}.workspace{display:grid;grid-template-columns:1fr;gap:16px}.workspace.detailed{grid-template-columns:minmax(0,1fr) minmax(300px,36%)}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px}.template-card,.detail,.history{padding:18px;border:1px solid var(--border-color);border-radius:20px;background:var(--bg-surface);box-shadow:var(--shadow-sm)}.card-head{display:flex;justify-content:space-between;gap:8px}.card-head h2{font-size:1.05rem;color:var(--text-strong)}.status,.badges span{padding:4px 8px;border-radius:999px;background:var(--primary-soft);color:var(--primary);font-size:.7rem;font-weight:800;height:max-content}.status.active{background:#dcfce7;color:#15803d}.preview{display:-webkit-box;overflow:hidden;-webkit-line-clamp:3;-webkit-box-orient:vertical;white-space:pre-wrap;color:var(--text-muted)}.badges,.card-actions{display:flex;flex-wrap:wrap;gap:6px}.template-card footer{margin-top:14px;padding-top:12px;border-top:1px solid var(--border-color)}.card-actions{margin-top:10px}.card-actions button,.row-actions button{padding:7px 10px;border:1px solid var(--border-color);border-radius:9px;background:var(--bg-surface-solid);color:var(--text-main)}.card-actions .danger,.row-actions .danger{color:var(--danger)}.row-actions{display:flex;gap:6px}.detail{position:sticky;top:100px;height:max-content}.detail-close{float:right;background:transparent;color:var(--text-muted);font-size:1.5rem}.detail pre{white-space:pre-wrap;font:inherit;padding:12px;background:var(--bg-soft);border-radius:12px}.period{display:flex;gap:8px}.history-filters{grid-template-columns:repeat(4,1fr);margin:16px 0;padding:0;border:0}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:1250px}th,td{padding:11px;border-bottom:1px solid var(--border-color);text-align:left;color:var(--text-main);font-size:.82rem}th{color:var(--text-faint)}@media(max-width:1000px){.stats{grid-template-columns:repeat(2,1fr)}.workspace.detailed{grid-template-columns:1fr}.detail{position:static}.filters{grid-template-columns:repeat(2,1fr)}.filters input{grid-column:1/-1}}@media(max-width:680px){.page-header,.section-head{align-items:stretch;flex-direction:column}.stats,.cards,.filters,.history-filters{grid-template-columns:1fr}.filters input{grid-column:auto}.region-tabs{width:100%}.region-tabs button{flex:1;min-width:0}.period{width:100%}.period>*{flex:1}.history{padding:14px}}
</style>
